import React, { useState } from 'react';
import { UserPlus, Mail, Lock, User, Phone } from 'lucide-react';

function Register() {
    const [user, setUser] = useState({
        fullname: '',
        email: '',
        password: '',
        phone: ''
    });
    const { fullname, email, password, phone } = user;

    const onInputChange = (e) => {
        setUser({ ...user, [e.target.name]: e.target.value });
    }

    const onSubmit = async() => {
        if (!fullname || !email || !password) {
            alert("Please fill in all required fields");
            return;
        }
        // Simulating registration
        console.log("Registering user:", user);
        alert("User registered successfully");
        // In your actual app: await axios.post("http://localhost:8080/user", user);
        // window.location.href = ("/login");
    }

    return (
        <div style={{
            minHeight: '100vh',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
            padding: '20px'
        }}>
            <div style={{
                background: 'white',
                padding: '40px',
                borderRadius: '15px',
                boxShadow: '0 10px 40px rgba(0,0,0,0.2)',
                width: '100%',
                maxWidth: '450px'
            }}>
                <div style={{ textAlign: 'center', marginBottom: '30px' }}>
                    <div style={{
                        width: '70px',
                        height: '70px',
                        background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                        borderRadius: '50%',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        margin: '0 auto 20px'
                    }}>
                        <UserPlus size={35} color="white" />
                    </div>
                    <h1 style={{
                        fontSize: '28px',
                        color: '#333',
                        margin: '0 0 10px 0',
                        fontWeight: '600'
                    }}>Create Account</h1>
                    <p style={{
                        color: '#666',
                        fontSize: '14px',
                        margin: 0
                    }}>Join us today and get started</p>
                </div>

                <div>
                    <div style={{ marginBottom: '20px' }}>
                        <label style={{
                            display: 'block',
                            marginBottom: '8px',
                            color: '#333',
                            fontSize: '14px',
                            fontWeight: '500'
                        }}>
                            <User size={16} style={{ verticalAlign: 'middle', marginRight: '5px' }} />
                            Full Name
                        </label>
                        <input
                            type="text"
                            name="fullname"
                            value={fullname}
                            onChange={onInputChange}
                            placeholder="Enter your full name"
                            style={{
                                width: '100%',
                                padding: '12px 15px',
                                border: '2px solid #e0e0e0',
                                borderRadius: '8px',
                                fontSize: '14px',
                                transition: 'all 0.3s',
                                outline: 'none',
                                boxSizing: 'border-box'
                            }}
                            onFocus={(e) => e.target.style.borderColor = '#667eea'}
                            onBlur={(e) => e.target.style.borderColor = '#e0e0e0'}
                        />
                    </div>

                    <div style={{ marginBottom: '20px' }}>
                        <label style={{
                            display: 'block',
                            marginBottom: '8px',
                            color: '#333',
                            fontSize: '14px',
                            fontWeight: '500'
                        }}>
                            <Mail size={16} style={{ verticalAlign: 'middle', marginRight: '5px' }} />
                            Email Address
                        </label>
                        <input
                            type="email"
                            name="email"
                            value={email}
                            onChange={onInputChange}
                            placeholder="Enter your email"
                            style={{
                                width: '100%',
                                padding: '12px 15px',
                                border: '2px solid #e0e0e0',
                                borderRadius: '8px',
                                fontSize: '14px',
                                transition: 'all 0.3s',
                                outline: 'none',
                                boxSizing: 'border-box'
                            }}
                            onFocus={(e) => e.target.style.borderColor = '#667eea'}
                            onBlur={(e) => e.target.style.borderColor = '#e0e0e0'}
                        />
                    </div>

                    <div style={{ marginBottom: '20px' }}>
                        <label style={{
                            display: 'block',
                            marginBottom: '8px',
                            color: '#333',
                            fontSize: '14px',
                            fontWeight: '500'
                        }}>
                            <Lock size={16} style={{ verticalAlign: 'middle', marginRight: '5px' }} />
                            Password
                        </label>
                        <input
                            type="password"
                            name="password"
                            value={password}
                            onChange={onInputChange}
                            placeholder="Create a password"
                            style={{
                                width: '100%',
                                padding: '12px 15px',
                                border: '2px solid #e0e0e0',
                                borderRadius: '8px',
                                fontSize: '14px',
                                transition: 'all 0.3s',
                                outline: 'none',
                                boxSizing: 'border-box'
                            }}
                            onFocus={(e) => e.target.style.borderColor = '#667eea'}
                            onBlur={(e) => e.target.style.borderColor = '#e0e0e0'}
                        />
                    </div>

                    <div style={{ marginBottom: '25px' }}>
                        <label style={{
                            display: 'block',
                            marginBottom: '8px',
                            color: '#333',
                            fontSize: '14px',
                            fontWeight: '500'
                        }}>
                            <Phone size={16} style={{ verticalAlign: 'middle', marginRight: '5px' }} />
                            Phone Number
                        </label>
                        <input
                            type="text"
                            name="phone"
                            value={phone}
                            onChange={onInputChange}
                            placeholder="Enter your phone number (optional)"
                            style={{
                                width: '100%',
                                padding: '12px 15px',
                                border: '2px solid #e0e0e0',
                                borderRadius: '8px',
                                fontSize: '14px',
                                transition: 'all 0.3s',
                                outline: 'none',
                                boxSizing: 'border-box'
                            }}
                            onFocus={(e) => e.target.style.borderColor = '#667eea'}
                            onBlur={(e) => e.target.style.borderColor = '#e0e0e0'}
                        />
                    </div>

                    <button
                        onClick={onSubmit}
                        style={{
                            width: '100%',
                            padding: '14px',
                            background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                            color: 'white',
                            border: 'none',
                            borderRadius: '8px',
                            fontSize: '16px',
                            fontWeight: '600',
                            cursor: 'pointer',
                            transition: 'all 0.3s',
                            boxShadow: '0 4px 15px rgba(102, 126, 234, 0.4)'
                        }}
                        onMouseOver={(e) => {
                            e.target.style.transform = 'translateY(-2px)';
                            e.target.style.boxShadow = '0 6px 20px rgba(102, 126, 234, 0.6)';
                        }}
                        onMouseOut={(e) => {
                            e.target.style.transform = 'translateY(0)';
                            e.target.style.boxShadow = '0 4px 15px rgba(102, 126, 234, 0.4)';
                        }}
                    >
                        Register
                    </button>
                </div>

                <p style={{
                    textAlign: 'center',
                    marginTop: '25px',
                    fontSize: '14px',
                    color: '#666'
                }}>
                    Already have an account?{' '}
                    <a href="/login" style={{
                        color: '#667eea',
                        textDecoration: 'none',
                        fontWeight: '600'
                    }}>
                        Login here
                    </a>
                </p>
            </div>
        </div>
    );
}

export default Register;
